# --------------------------------------------------------------------------
# 6.  gazetteer of canonical roots
# --------------------------------------------------------------------------

RESOLVE_BASE = 0.55
RESOLVE_PER = 0.105
PAIR_BASE = 0.60
PAIR_PER = 0.105


def thresh(k1, k2, base=RESOLVE_BASE, per=RESOLVE_PER):
    return base + per * min(len(k1), len(k2))


def _ru_masculine(f: str) -> str:
    """Russian feminine surname -> masculine base."""
    for suf, rep in (("skaya", "sky"), ("skaia", "sky"), ("ckaja", "sky"),
                     ("tskaya", "tsky"), ("zkaya", "zky")):
        if f.endswith(suf):
            return f[: -len(suf)] + rep
    for suf in ("ova", "eva", "ina", "yna", "aya"):
        if f.endswith(suf) and len(f) > 5:
            return f[:-1]
    return f


class Gazetteer:
    def __init__(self):
        self.index = {}            # phonetic key -> set(root ids)
        self.root_keys = {}        # root id -> canonical key
        self.root_skel = {}        # root id -> consonant skeleton
        self.by_len = {}           # length -> [(key, root_id)]
        self.cache = {}

    # -- construction ------------------------------------------------------
    def add_key(self, key, root):
        if not key:
            return
        s = self.index.get(key)
        if s is None:
            self.index[key] = {root}
        else:
            s.add(root)

    def add_root(self, folded):
        """Register a canonical name form; returns its root id."""
        base = _ru_masculine(strip_article(folded))
        if not base:
            return None
        root = base
        if root not in self.root_keys:
            self.root_keys[root] = pkey(base)
            self.root_skel[root] = skeleton(pkey(base))
            for v in gen_variants(base):
                self.add_key(pkey(v), root)
            self.add_key(pkey(strip_surname_prefix(base)), root)
        self.add_key(pkey(folded), root)
        self.add_key(pkey(base), root)
        return root

    def finish(self):
        by_len = {}
        for root, key in self.root_keys.items():
            by_len.setdefault(len(key), []).append((key, root))
        self.by_len = by_len

    # -- resolution --------------------------------------------------------
    def lookup(self, key):
        return self.index.get(key)

    def fuzzy(self, key, extra=0.0):
        """Nearest canonical roots for a phonetic key."""
        if not key:
            return None
        best = None
        bestd = 9.9
        lim = thresh(key, key) + extra
        for ln in range(max(1, len(key) - 4), len(key) + 5):
            for k2, root in self.by_len.get(ln, ()):
                t = min(thresh(key, k2) + extra, lim + 0.5)
                d = wdist(key, k2, cap=t)
                if d <= t and d < bestd - 1e-9:
                    bestd = d
                    best = {root}
                elif best is not None and abs(d - bestd) <= 1e-9:
                    best.add(root)
        return best

    def resolve(self, tok):
        k = tok.key
        if k in self.cache:
            tok.roots = self.cache[k]
            return tok.roots
        r = self.index.get(k)
        if r is None:
            k2 = pkey(strip_surname_prefix(tok.fold))
            if k2 != k:
                r = self.index.get(k2)
        if r is None:
            k3 = pkey(strip_article(tok.fold))
            if k3 != k:
                r = self.index.get(k3)
        if r is None and tok.script != "latin":
            r = self._resolve_script(tok)
        if r is None:
            r = self.fuzzy(k)
        r = frozenset(r) if r else None
        self.cache[k] = r
        tok.roots = r
        return r

    def _resolve_script(self, tok):
        """Original-script token that the watchlist alignment did not cover."""
        sk = skeleton(tok.key)
        if len(sk) < 2:
            return None
        best, bestd = None, 9.9
        for root, rsk in self.root_skel.items():
            if abs(len(rsk) - len(sk)) > 2:
                continue
            d = wdist(sk, rsk, cap=1.0)
            if d <= 0.55 and d < bestd - 1e-9:
                bestd, best = d, {root}
            elif best is not None and abs(d - bestd) <= 1e-9:
                best.add(root)
        return best


def build_gazetteer(entries):
    g = Gazetteer()
    people = [e for e in entries if e.get("type") == "individual"]
    # 1. canonical roots come from latin primary names
    latin_names = []
    for e in people:
        pn = e.get("primary_name") or ""
        if script_of(pn) == "latin":
            latin_names.append((e, PersonName(pn)))
            for t in PersonName(pn).core:
                g.add_root(t.fold)
    # entries with no latin primary name: use a latin strong alias
    for e in people:
        pn = e.get("primary_name") or ""
        if script_of(pn) != "latin":
            for a in e.get("aliases") or ():
                if a.get("strength") == "strong" and script_of(a["name"]) == "latin":
                    for t in PersonName(a["name"]).core:
                        g.add_root(t.fold)
                    break
    for a, b in CROSS_POOL:
        ra = g.index.get(pkey(a))
        rb = g.index.get(pkey(b))
        if ra and rb:
            for r in list(ra) + list(rb):
                g.add_key(pkey(a), r)
                g.add_key(pkey(b), r)
    for nick, fulls in NICKNAMES.items():
        for full in fulls:
            roots = g.index.get(pkey(full))
            if roots:
                for r in list(roots):
                    for v in gen_variants(nick):
                        g.add_key(pkey(v), r)
    g.finish()

    # 2. mine variant spellings from the entries themselves: strong aliases and
    #    original-script names of the same entry denote the same person.
    def align(dst_tokens, src_tokens):
        """map dst tokens onto src tokens (same person) -> index additions"""
        used = set()
        for dt in dst_tokens:
            if dt.key in g.index:
                continue
            best, bestd = None, 9.9
            for i, st in enumerate(src_tokens):
                if i in used:
                    continue
                roots = g.resolve(st)
                if not roots:
                    continue
                if dt.script != "latin" or st.script != "latin":
                    d = wdist(skeleton(dt.key), skeleton(st.key), cap=2.0) + 0.3
                else:
                    d = wdist(dt.key, st.key, cap=3.0)
                if d < bestd:
                    bestd, best = d, i
            if best is not None and bestd <= 2.2:
                used.add(best)
                for r in g.resolve(src_tokens[best]):
                    g.add_key(dt.key, r)

    for rounds in range(2):
        for e in people:
            forms = []
            pn = e.get("primary_name") or ""
            if pn:
                forms.append(PersonName(pn))
            sn = e.get("script_name") or ""
            if sn and sn != pn:
                forms.append(PersonName(sn))
            for a in e.get("aliases") or ():
                if a.get("strength") == "strong":
                    forms.append(PersonName(a["name"]))
            if len(forms) < 2:
                continue
            # the most resolvable form is the reference
            scored = []
            for f in forms:
                ok = sum(1 for t in f.core if g.resolve(t))
                scored.append((ok - 0.01 * len(f.core), f))
            scored.sort(key=lambda x: -x[0])
            ref = scored[0][1]
            for _, f in scored[1:]:
                align(f.core, ref.core)
                align(ref.core, f.core)
    return g


# --------------------------------------------------------------------------
# 7.  name comparison
# --------------------------------------------------------------------------

def tok_equiv(a, b):
    if a.key == b.key:
        return True
    ra, rb = a.roots, b.roots
    if ra and rb:
        return bool(ra & rb)
    if a.script != "latin" or b.script != "latin":
        ska, skb = skeleton(a.key), skeleton(b.key)
        return wdist(ska, skb, cap=1.0) <= 0.5
    d = wdist(a.key, b.key, cap=2.0)
    return d <= thresh(a.key, b.key, PAIR_BASE, PAIR_PER)


def _bipartite(a, b):
    """perfect matching between two equal-size token lists"""
    n = len(a)
    if n != len(b):
        return False
    adj = []
    for ta in a:
        row = [j for j, tb in enumerate(b) if tok_equiv(ta, tb)]
        if not row:
            return False
        adj.append(row)
    match = [-1] * n

    def try_k(i, seen):
        for j in adj[i]:
            if j in seen:
                continue
            seen.add(j)
            if match[j] == -1 or try_k(match[j], seen):
                match[j] = i
                return True
        return False

    for i in range(n):
        if not try_k(i, set()):
            return False
    return True


def _merge_forms(toks):
    """token list plus variants where two adjacent tokens are glued together"""
    out = [toks]
    n = len(toks)
    if n >= 2:
        for i in range(n - 1):
            merged = toks[i].fold + toks[i + 1].fold
            t = Tok(toks[i].raw + toks[i + 1].raw, merged, pkey(merged),
                    toks[i].script)
            out.append(toks[:i] + [t] + toks[i + 2:])
    return out


def name_forms(pn):
    forms = [pn.core]
    if pn.nasab:
        forms.append(pn.core + pn.nasab)
    return forms


def names_equiv(pa, pb, gaz, min_tokens=2):
    fa = name_forms(pa)
    fb = name_forms(pb)
    for a in fa:
        if len(a) < min_tokens:
            continue
        for b in fb:
            if len(b) < min_tokens:
                continue
            if len(a) == len(b):
                if _bipartite(a, b):
                    return True
            elif abs(len(a) - len(b)) == 1:
                if len(a) > len(b):
                    for am in _merge_forms(a)[1:]:
                        for t in am:
                            if t.roots is None:
                                gaz.resolve(t)
                        if _bipartite(am, b):
                            return True
                else:
                    for bm in _merge_forms(b)[1:]:
                        for t in bm:
                            if t.roots is None:
                                gaz.resolve(t)
                        if _bipartite(a, bm):
                            return True
    return False


# --------------------------------------------------------------------------
# 8.  entities and vessels
# --------------------------------------------------------------------------

_CH_ALIAS = {}
for _py, _alts in CHINESE.items():
    for _a in _alts:
        _CH_ALIAS.setdefault(_a, set()).add(_py)

SKIP_WORDS = {"and", "the", "of", "für", "fur"}


def org_words(name, kind, pinyin_stems=frozenset()):
    raw = name.replace("&", " and ")
    parts = split_tokens(raw)
    words = []
    for p in parts:
        f = fold(p)
        if not f:
            continue
        low = p.lower().strip(". ")
        if kind == "vessel" and (low in VESSEL_PREFIX or f in
                                 ("mv", "mt", "ms", "ss", "vessel")):
            if not words:
                continue
        if kind == "entity" and f in LEGAL:
            continue
        if f in SKIP_WORDS and not words:
            continue
        if f in ("and",):
            continue
        words.append(f)
    return words


def word_variants(w, pinyin_stems):
    out = {w}
    a = strip_article(w)
    if a != w:
        out.add(a)
    if w not in pinyin_stems:
        for py in _CH_ALIAS.get(w, ()):
            out.add(py)
    return out


def org_equiv(wa, wb, pinyin_stems):
    if len(wa) != len(wb):
        return False
    for x, y in zip(wa, wb):
        if x == y:
            continue
        vx = word_variants(x, pinyin_stems)
        vy = word_variants(y, pinyin_stems)
        if vx & vy:
            continue
        kx, ky = pkey(strip_article(x)), pkey(strip_article(y))
        if kx == ky:
            continue
        if wdist(kx, ky, cap=0.5) <= 0.35:
            continue
        return False
    return True

