#!/usr/bin/env python3
import csv, json, sys
import engine as E

wl = json.load(open('watchlist.json'))
byuid = {e['uid']: e for e in wl}
scr = E.Screener(wl)


def show_name(n, kind='individual'):
    if kind == 'individual':
        pn = E.PersonName(n)
        for t in pn.core + pn.nasab:
            scr.gaz.resolve(t)
        print('   %-42r core=%s nasab=%s' % (n, [(t.fold, t.key, sorted(t.roots) if t.roots else None) for t in pn.core], [(t.fold, t.roots) for t in pn.nasab]))
    else:
        print('   %-42r words=%s' % (n, E.org_words(n, kind)))


def dump(cust_name, uid=None, kind='individual', dob=''):
    print('CUSTOMER:')
    show_name(cust_name, kind)
    if uid:
        e = byuid[uid]
        print('ENTRY %s type=%s dob=%s ids=%s' % (uid, e['type'], e['dob'], e['ids']))
        for f in [e['primary_name'], e['script_name']] + [a['name'] + ' [' + a['strength'] + ']' for a in e['aliases']]:
            if f:
                show_name(f.split(' [')[0], e['type'])
        if kind == 'individual':
            pa = E.PersonName(cust_name)
            for t in pa.core + pa.nasab:
                scr.gaz.resolve(t)
            for f in [e['primary_name'], e['script_name']] + [a['name'] for a in e['aliases'] if a['strength'] == 'strong']:
                if not f:
                    continue
                pb = E.PersonName(f)
                for t in pb.core + pb.nasab:
                    scr.gaz.resolve(t)
                print('   equiv(%r) = %s' % (f, E.names_equiv(pa, pb, scr.gaz)))
    print('PREDICTED:', scr.screen({'full_name': cust_name, 'dob': dob, 'type': kind,
                                    'id_type': '', 'id_number': ''}))


if __name__ == '__main__':
    args = sys.argv[1:]
    name = args[0]
    uid = args[1] if len(args) > 1 and args[1].startswith('SDN') else None
    kind = 'individual'
    for a in args:
        if a in ('entity', 'vessel'):
            kind = a
    dob = ''
    for a in args:
        if a[:4].isdigit() and '-' in a or (len(a) == 4 and a.isdigit()):
            dob = a
    dump(name, uid, kind, dob)

