def sdist(a: str, b: str, cap: float = 2.0) -> float:
    """Distance between a script-derived key and a latin key."""
    la, lb = len(a), len(b)
    if not la or not lb:
        return 3.0
    prev = [0.0] * (lb + 1)
    for j in range(1, lb + 1):
        prev[j] = prev[j - 1] + _SIND.get(b[j - 1], _DEF_INDEL)
    for i in range(1, la + 1):
