            if d < v:
                v = d
            cur[j] = v
            if v < best:
                best = v
        if best > cap:
            return cap + 1.0
        prev = cur
    return prev[lb]


def script_keys(folded: str) -> list:
    """Readings of a transliterated arabic/persian token (w/y ambiguity)."""
