"""List NO_MATCH customers that nearly matched an entry (one token off)."""
import csv, json, sys, collections
import engine as E

wl = json.load(open('watchlist.json'))
scr = E.Screener(wl)
path = sys.argv[1] if len(sys.argv) > 1 else 'customers.csv'
rows = list(csv.DictReader(open(path)))
dec = {r['customer_id']: r for r in csv.DictReader(open(sys.argv[2]))} if len(sys.argv) > 2 else None

out = collections.Counter()
n = 0
for r in rows:
    if (r.get('type') or 'individual') != 'individual':
        continue
    if scr.screen(r):
        continue
    pn = E.PersonName(r['full_name'])
    for t in pn.core + pn.nasab:
        scr.gaz.resolve(t)
    if len(pn.core) < 2:
        continue
    cand = collections.Counter()
    for t in pn.core:
        if t.roots:
            for root in t.roots:
                for idx in scr.root_index.get(root, ()):
                    cand[idx] += 1
    best = [i for i, c in cand.items() if c >= len(pn.core) - 1 and c >= 1]
    shown = 0
    for idx in best:
        e = scr.entries[idx]
        if e.type != 'individual':
            continue
        for form in e.names:
            if len(form.core) != len(pn.core):
                continue
            # count token mismatches
            miss = [(a.raw, a.key, sorted(a.roots) if a.roots else None,
                     b.raw, b.key, sorted(b.roots) if b.roots else None)
                    for a, b in zip(pn.core, form.core)
                    if not E.tok_equiv(a, b)]
            if len(miss) == 1 and shown < 1:
                ok, corr = E.dob_compatible(E.norm_dob(r['dob']), e.dob)
                print('%-38s %-10s | %-32s %-10s dobok=%s | %s' % (
                    r['full_name'], r['dob'], form.raw, e.dob, ok, miss[0]))
                shown += 1
                n += 1
print('total near misses', n)

