#!/usr/bin/env python3
"""End-to-end stress test.

Synthesises customers from the watchlist under the romanisation conventions the
hidden batch is said to use, stacks random perturbations on top, and checks
that the engine still matches (and that decoys still do not).
"""
import json, random, re, sys, unicodedata, collections
import engine as E

random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 11)

wl = json.load(open('watchlist.json'))
scr = E.Screener(wl)

# ---------------------------------------------------------------- conventions


def _sub(s, pairs):
    for a, b in pairs:
        s = re.sub(a, b, s)
    return s


def turkish(s):
    s = _sub(s, [(r"j", "c"), (r"q", "k"), (r"kh", "h"), (r"sh", "ş"),
                 (r"ch", "ç"), (r"th", "t"), (r"d$", "t"), (r"ou", "u"),
                 (r"w", "v")])
    if random.random() < 0.5:
        s = s.replace("i", "ı", 1)
    if random.random() < 0.5:
        s = re.sub(r"u", "ü", s, count=1)
    return s


def indonesian(s):
    return _sub(s, [(r"sh", "sj"), (r"kh", "ch"), (r"j", "dj"), (r"u", "oe"),
                    (r"^y", "j"), (r"y", "j"), (r"q", "k"), (r"c", "tj")])


def scientific(s):
    return _sub(s, [(r"shch", "sc"), (r"sh", "s"), (r"ch", "c"), (r"zh", "z"),
                    (r"kh", "h"), (r"ts", "c"), (r"yu", "ju"), (r"ya", "ja"),
                    (r"ye", "e"), (r"y$", "ij"), (r"^y", "j"), (r"y", "j")])


def polish(s):
    return _sub(s, [(r"shch", "szcz"), (r"sh", "sz"), (r"ch", "cz"),
                    (r"zh", "z"), (r"kh", "ch"), (r"v", "w"), (r"^ye", "je"),
                    (r"ya", "ja"), (r"yu", "ju"), (r"y", "y")])


def french(s):
    return _sub(s, [(r"shch", "chtch"), (r"sh", "ch"), (r"ch", "tch"),
                    (r"zh", "j"), (r"ov$", "off"), (r"ev$", "eff"),
                    (r"u", "ou"), (r"j", "dj"), (r"y$", "i")])


def german(s):
    return _sub(s, [(r"shch", "schtsch"), (r"sh", "sch"), (r"ch", "tsch"),
                    (r"zh", "sch"), (r"kh", "ch"), (r"v", "w"), (r"ts", "z"),
                    (r"^y", "j"), (r"ya", "ja"), (r"yu", "ju"), (r"y", "j"),
                    (r"j$", "j")])


def gulf(s):
    s = _sub(s, [(r"q", random.choice(["g", "q", "k", "gh"])),
                 (r"th", "t"), (r"dh", "d")])
    if random.random() < 0.4:
        s = _sub(s, [(r"j", random.choice(["j", "g", "dj"]))])
    return s


CONV = {"turkish": turkish, "indonesian": indonesian, "scientific": scientific,
        "polish": polish, "french": french, "german": german, "gulf": gulf}

VOWELS = "aeiou"


def perturb(s):
    """small orthographic noise stacked on top of a convention"""
    n = random.randint(0, 2)
    for _ in range(n):
        k = random.random()
        idx = [i for i, c in enumerate(s) if c in VOWELS]
        if k < 0.3 and idx:
            i = random.choice(idx)
            s = s[:i] + random.choice("aeiou") + s[i + 1:]
        elif k < 0.5 and len(s) > 3:
            i = random.randrange(1, len(s) - 1)
            if s[i] not in VOWELS:
                s = s[:i] + s[i] + s[i:]
        elif k < 0.7 and s[-1] not in VOWELS:
            s = s + random.choice("eh")
        elif k < 0.85 and idx:
            i = random.choice(idx)
            s = s[:i] + s[i] * 2 + s[i + 1:]
    return s


ART = ["al-", "el-", "Al ", "El ", "", "al ", ""]
SUN = "tdrzsn"


def article_form(word):
    """re-spell an arabic family name's article, sometimes assimilated"""
    stem = re.sub(r"^(al|el|as|ash|ad|at|an|ar|az)[- ]", "", word, flags=re.I)
    if stem == word:
        return word
    style = random.random()
    first = stem[0].lower()
    if style < 0.25 and first in SUN:
        return "a" + first + "-" + stem
    if style < 0.4:
        return "El" + stem[0].upper() + stem[1:]
    if style < 0.55:
        return stem
    return random.choice(ART) + stem


def restyle(name, conv):
    """apply a convention to every word of a (latin) name"""
    out = []
    for w in name.split():
        low = w.lower()
        if low in ("bin", "ibn", "ben", "b.", "al", "el", "de", "la", "du",
                   "van", "der", "le"):
            out.append(w)
            continue
        s = CONV[conv](low)
        s = perturb(s)
        out.append(s.capitalize())
    return " ".join(out)


def restructure(name, entry):
    """name order, patronymics, nasab, initials"""
    toks = name.split()
    r = random.random()
    if r < 0.2 and len(toks) >= 2:
        toks = toks[1:] + toks[:1]
    elif r < 0.35 and len(toks) >= 2:
        toks = [toks[-1] + ","] + toks[:-1]
    if random.random() < 0.15 and len(toks) >= 2:
        toks.insert(1, random.choice("ABCDJMR") + ".")
    return " ".join(toks)


def canon_tokens(name):
    pn = E.PersonName(name)
    return tuple(sorted(t.fold for t in pn.core))


# ------------------------------------------------------------------ expected
people = [e for e in wl if e['type'] == 'individual'
          and E.script_of(e['primary_name']) == 'latin']
bycanon = collections.defaultdict(list)
for e in wl:
    if e['type'] != 'individual':
        continue
    for nm in [e['primary_name']] + [a['name'] for a in e['aliases']
                                     if a['strength'] == 'strong']:
        if E.script_of(nm) == 'latin':
            bycanon[canon_tokens(nm)].append(e)


def expected_uid(entry, dob):
    """uid the policy asks for: id, then dob support, then lowest uid"""
    cands = []
    for e in bycanon.get(canon_tokens(entry['primary_name']), []):
        ok, corr = E.dob_compatible(E.norm_dob(dob), E.norm_dob(e['dob']))
        if ok:
            cands.append((0 if corr else 1, e['uid']))
    if not cands:
        return None
    return sorted(cands)[0][1]


# ------------------------------------------------------------------ run
def run(n=400):
    stats = collections.Counter()
    fails = []
    convs = list(CONV)
    for i in range(n):
        e = random.choice(people)
        conv = random.choice(convs)
        name = e['primary_name']
        words = []
        for w in name.split():
            words.append(article_form(w))
        name2 = restyle(" ".join(words), conv)
        name2 = restructure(name2, e)
        dob = E.norm_dob(e['dob'])
        pick = random.random()
        if pick < 0.3 or not dob:
            cdob = ''
        elif pick < 0.5 and len(dob) == 10:
            cdob = dob[:4]
        elif pick < 0.6 and len(dob) == 10:
            cdob = dob[:7]
        else:
            cdob = dob
        want = expected_uid(e, cdob)
        got = scr.screen({'full_name': name2, 'dob': cdob, 'type': 'individual',
                          'id_type': '', 'id_number': ''})
        stats[conv + ':n'] += 1
        if got and (got == want or want is None):
            stats[conv + ':ok'] += 1
        elif got and want and got != want:
            stats[conv + ':uid'] += 1
            fails.append(('UID', conv, e['primary_name'], name2, cdob, got, want))
        else:
            stats[conv + ':miss'] += 1
            fails.append(('MISS', conv, e['primary_name'], name2, cdob, got, want))
    return stats, fails


if __name__ == '__main__':
    stats, fails = run(int(sys.argv[2]) if len(sys.argv) > 2 else 500)
    tot = ok = 0
    for c in CONV:
        n, k = stats[c + ':n'], stats[c + ':ok']
        tot += n
        ok += k
        print('%-12s n=%-4d recall=%.3f  (uid errors %d)' %
              (c, n, k / n if n else 1, stats[c + ':uid']))
    print('TOTAL recall %.4f  (%d/%d)' % (ok / tot, ok, tot))
    for f in fails[:45]:
        print('  %-5s %-11s %-34s %-40s %-10s got=%s want=%s' % f)

